// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    address owner;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
        owner = c.owner();
    }

    function testFuzz_property(address target, uint256 amount) public {
        vm.assume(target != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);

        uint256 balBefore = c.balanceOf(target);
        uint256 supplyBefore = c.totalSupply();

        vm.prank(owner);
        c.mintToken(target, amount);

        assertTrue(
            c.balanceOf(target) == balBefore + amount && c.totalSupply() == supplyBefore + amount,
            "mintToken must credit target balance and increase totalSupply by mintedAmount"
        );
    }
}
